<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {usePhasePage} from '../phasePage'
import {storeToday} from '../time'
import {leaveKind,type EncashContext,type EncashClassification,type EncashDocument} from '../complianceTypes'
import type {PayProfilePage} from '../payrollTypes'
import type {Option} from '../types'
import BusinessSteps from '../components/BusinessSteps.vue'
import PhaseStatus from '../components/PhaseStatus.vue'
const {api,base,english,loading,busy,failure,notice,load,write}=usePhasePage(),route=useRoute()
const company=ref(String(route.query.companyId||'')),companies=ref<Option[]>([]),people=ref<Option[]>([]),employee=ref(String(route.query.employeeId||'')),step=ref(0),context=ref<EncashContext|null>(null),documents=ref<EncashDocument[]>([])
const account=ref(''),quantity=ref(0),valuationOn=ref(storeToday()),payableOn=ref(storeToday()),purpose=ref('termination'),evidence=ref(''),classifications=ref<EncashClassification[]>([]),channel=ref('monthly'),created=ref<EncashDocument|null>(null)
const balance=computed(()=>context.value?.balances.find(b=>b.account.id===account.value))
const quote=ref<{valuation:EncashDocument['valuation'];available:number;issues:string[]}|null>(null)
function body(){return {employeeId:employee.value,accountId:account.value,quantity:quantity.value,valuationOn:valuationOn.value,payableOn:payableOn.value,purpose:purpose.value,evidence:evidence.value,classifications:classifications.value,route:channel.value,originMonth:payableOn.value.slice(0,7)}}
watch(()=>JSON.stringify(body()),()=>{quote.value=null})
function preview(){void write(async()=>{quote.value=await api().post('/leave-encashments/preview',body())})}
let pending:{id:string;body:unknown}|null=null
function peopleLoad(){context.value=null;people.value=[];if(!company.value)return;void load(()=>api().get<PayProfilePage>('/pay-profiles?companyId='+company.value),p=>{people.value=p.employees;if(employee.value&&people.value.some(e=>e.id===employee.value))select()})}
function select(){if(!employee.value||pending)return;void load(async()=>({c:await api().get<EncashContext>(`/leave-encashments/context?employeeId=${employee.value}&year=${Number(valuationOn.value.slice(0,4))}`),d:await api().get<EncashDocument[]>('/leave-encashments?employeeId='+employee.value)}),r=>{context.value=r.c;documents.value=r.d;account.value=r.c.balances[0]?.account.id||'';quantity.value=0;classifications.value=(r.c.profile?.rule.items||[]).map(i=>({itemId:i.itemId||'',included:false,reason:''}))})}
function submit(){if(!quote.value&&!pending)return;if(!balance.value||quantity.value<=0||quantity.value>balance.value.available)return;if(!pending)pending={id:crypto.randomUUID(),body:{...body(),expectedValuation:quote.value?.valuation}};const request=pending;void write(async()=>{created.value=await api().put<EncashDocument>('/leave-encashments/'+request.id,request.body);pending=null;step.value=2})}
onMounted(()=>{void load(()=>api().get<{companies:Option[]}>('/payroll-home'),h=>{companies.value=h.companies;if(!h.companies.some(c=>c.id===company.value))company.value=h.companies[0]?.id||'';peopleLoad()})})
</script>
<template><section class="wf-panel"><header class="wf-toolbar"><h2>{{english()?'Unused leave encashment':'未休年假折现'}}</h2><RouterLink :to="base+'/payroll'">{{english()?'Payroll workspace':'工资工作台'}}</RouterLink></header><p class="wf-hint">{{english()?'Separate from overtime. Reconcile leave, review the gross rate, then use the existing wage approval and formal payroll.':'与加班分账。先核对年假余额及合法依据，再核对折现基数，提交现有工资审批；正式计薪确认时核销额度。'}}</p><PhaseStatus :loading="loading" :failure="failure" :notice="notice"/><BusinessSteps v-model="step" :disabled="busy||!!pending" :steps="english()?['Employee & entitlement','Gross rate & approval','Formal payroll']:['员工与额度','折现基数与审批','正式计薪']"/><div v-show="step===0"><div class="wf-grid"><label>{{english()?'Paying company':'发薪公司'}}<select v-model="company" :disabled="busy||!!pending" @change="employee='';peopleLoad()"><option v-for="c in companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>{{english()?'Employee':'员工'}}<select v-model="employee" :disabled="busy||!!pending" @change="select"><option value="" disabled>{{english()?'Choose employee':'选择员工'}}</option><option v-for="p in people" :key="p.id" :value="p.id">{{p.name}}</option></select></label></div><template v-if="context"><p v-if="!context.balances.length" class="wf-hint">{{english()?'No eligible leave account. Reconcile the employee contract and opening balance first.':'尚无可折现账户；请先核对员工合同并启用期初额度。'}}</p><div class="wf-grid"><label>{{english()?'Leave account':'假期账户'}}<select v-model="account"><option v-for="b in context.balances" :key="b.account.id" :value="b.account.id">{{b.account.year}} · {{leaveKind(b.account.kind,english())}} · {{b.available}} {{b.account.unit==='day'?(english()?'days':'天'):(english()?'hours':'小时')}}</option></select></label><label>{{english()?'Quantity':'折现数量'}}<input v-model.number="quantity" type="number" min="0.000001" :max="balance?.available" step="0.000001" required></label><label>{{english()?'Valuation / termination date':'计价／离职日'}}<input v-model="valuationOn" type="date" required @change="select"></label><label>{{english()?'Contractual payable date':'约定应付日'}}<input v-model="payableOn" type="date" :min="valuationOn" required></label><label>{{english()?'Legal purpose':'办理依据'}}<select v-model="purpose"><option value="termination">{{english()?'Ordinary termination settlement':'普通离职结清（核对未抵扣通知期）'}}</option><option value="contractual">{{english()?'Non-Part-IV contractual annual leave':'非第四部分合同允许的年假折现'}}</option><option value="company_extra">{{english()?'Additional company leave by contract':'合同允许的企业额外假'}}</option></select></label></div><p class="wf-hint">{{english()?'Statutory leave that must be taken or carried forward is not automatically cashed out. Misconduct dismissal and leave offsetting notice require separate review.':'法定须休用／结转部分不自动买断；失当解雇或以年假抵扣通知期等例外须另行核对，不得重复折现。'}}</p><footer class="wf-form-actions"><button class="primary" :disabled="!balance||quantity<=0||quantity>balance.available||!!balance.issues.length" @click="step=1">{{english()?'Next: gross rate':'下一步：核对折现基数'}}</button></footer></template></div><form v-if="context" v-show="step===1" @submit.prevent="quote||pending?submit():preview()"><fieldset :disabled="busy||!!pending"><h3>{{context.employeeName}} · {{english()?'Gross rate components':'折现工资基数核对'}}</h3><p>{{english()?'Basic pay':'基本工资'}}: {{context.profile?.rule.rate}} · {{context.profile?.rule.basis}}</p><p class="wf-hint">{{english()?'Include eligible fixed duty allowances only. Overtime, bonuses, reimbursements, productivity, travel, food and housing allowances are excluded. Do not infer from labels.':'核对固定职务等适用津贴；排除加班、奖金、报销、生产奖励、交通、餐食及住房津贴。不能仅凭名称判断。月津贴按合同工时折算，不直接加到小时单价。'}}</p><article v-for="(item,i) in context.profile?.rule.items||[]" :key="item.itemId||i" class="wf-history"><strong>{{item.label}} · {{item.amount}}</strong><label>{{english()?'Gross rate classification':'是否计入折现基数'}}<select v-model="classifications[i]!.included"><option :value="false">{{english()?'Excluded':'不计入'}}</option><option :value="true" :disabled="item.kind!=='ow_allowance'">{{english()?'Eligible fixed allowance':'计入适用固定津贴'}}</option></select></label><label>{{english()?'Classification evidence':'分类依据'}}<input v-model="classifications[i]!.reason" required maxlength="500"></label></article><label>{{english()?'Settlement route':'计薪方式'}}<select v-model="channel"><option value="monthly">{{english()?'Current open payroll / segmented settlement':'纳入未确认月度／分段工资'}}</option><option value="supplemental">{{english()?'Independent supplemental payroll':'独立补发（不改正式工资）'}}</option></select></label><label>{{english()?'Contract and eligibility evidence':'合同及资格核对说明'}}<textarea v-model="evidence" rows="3" maxlength="1000" required/></label></fieldset><dl v-if="quote" class="wf-details"><dt>{{english()?'Encashment amount (before CPF)':'折现金额（扣CPF前）'}}</dt><dd>{{quote.valuation.amount}}</dd><dt>{{english()?'Unit rate':'单价'}}</dt><dd>{{quote.valuation.unitRate}}</dd><dt>{{english()?'Basis':'计价依据'}}</dt><dd>{{quote.valuation.formula}}</dd></dl><p v-if="pending" class="wf-hint">{{english()?'Result uncertain. Retry sends the identical request.':'提交结果待确认，重试会发送同一请求。'}}</p><footer class="wf-form-actions"><button v-if="!pending" type="button" @click="step=0">{{english()?'Previous':'上一步'}}</button><button class="primary" :disabled="busy">{{pending?(english()?'Retry original request':'重试原请求'):quote?(english()?'Confirm amount & submit':'确认金额并提交审批'):(english()?'Preview encashment amount':'预览折现金额')}}</button></footer></form><div v-show="step===2"><template v-if="created"><h3>{{english()?'Submitted for independent approval':'已提交，等待他人审批'}}</h3><dl class="wf-details"><dt>{{english()?'Formula':'计价公式'}}</dt><dd>{{created.valuation.formula}}</dd><dt>{{english()?'Unit rate':'折现单价'}}</dt><dd>{{created.valuation.unitRate}}</dd><dt>{{english()?'Encashment amount':'折现金额'}}</dt><dd>{{created.valuation.amount}}</dd></dl></template><p>{{english()?'Approve the wage request, calculate payroll, check employee details, confirm, then publish. Approved encashment remains reserved until formal confirmation.':'工资变更由他人审批后，再测算、检查个人明细、正式确认及发布工资单。审批后仍为占用，正式确认时才核销；不会重复计入月末工资。'}}</p><p v-if="channel==='supplemental'" class="wf-hint">{{english()?'First reconcile original withholding and company SDL facts for the payable month. Unknown amounts cannot be treated as zero.':'独立补发前，先核对该应付月的原扣缴责任和公司SDL基线；未知金额不能按零处理。'}} <RouterLink :to="{path:base+'/statutory-settlement',query:{companyId:company,employeeId:employee,month:payableOn.slice(0,7)}}">{{english()?'Review statutory facts':'核对法定缴费资料'}}</RouterLink></p><nav class="wf-inline"><RouterLink class="wf-button primary" :to="{path:base+'/pay-change-requests',query:{companyId:company}}">{{english()?'Review wage request':'进入工资变更审批'}}</RouterLink><RouterLink :to="{path:base+(channel==='supplemental'?'/supplemental-payroll':'/payroll'),query:{companyId:company}}">{{english()?'Continue payroll':'继续计薪'}}</RouterLink></nav></div><details v-if="documents.length" class="wf-section"><summary>{{english()?'Previous encashments':'已有折现办理'}}</summary><article v-for="d in documents" :key="d.id" class="wf-history"><strong>{{d.valuation.amount}}</strong> · {{({reserved:english()?'Reserved / awaiting approval':'已占用／待审批',approved:english()?'Approved / awaiting payroll':'已批／待计薪',released:english()?'Released':'已释放',consumed:english()?'Settled':'已正式结算'} as Record<string,string>)[d.status]||d.status}}<p>{{d.valuation.formula}}</p></article></details></section></template>
